import java.util.*;
import java.io.*;
import java.lang.Math;

public class Main {
    static int mod;

    static List<Integer> readInput(Scanner sc, int n) {
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(sc.nextInt());
        }
        return list;
    }

    static int ceilingDivision(int a, int b) {
        return (a + b - 1) / b;
    }

    static int addMod(int a, int b) {
        return (a + b) % mod;
    }

    static int multiplyMod(int a, int b) {
        return (int)((long)a * b % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        mod = sc.nextInt();

        List<Integer> mem = new ArrayList<>();
        mem.add(0);
        mem.add(1);
        int totalSum = 1;

        for (int i = 2; i <= n; i++) {
            int limit = (int)Math.sqrt(i) + 1;
            int current = totalSum;

            for (int f = 2; f < limit; f++) {
                current = addMod(current, mem.get(i / f));
            }

            int boundary = i;
            for (int j = 1; j <= i / limit; j++) {
                int nextVal = i / (j + 1);
                current = addMod(current, multiplyMod(boundary - nextVal, mem.get(j)));
                boundary = nextVal;
            }

            totalSum = addMod(totalSum, current);
            mem.add(current);
        }

        System.out.println(mem.get(mem.size() - 1));
        sc.close();
    }
}
